content = open('extracted_heroes.txt').read()
lines = content.strip().split('\n')

# Parse first section (height data)
height_data = {}
for line in lines[:-38]:
    parts = line.split(',')
    if len(parts) == 3:
        hero_id = parts[0].strip()
        height = parts[1].strip()
        if height and height != 'None':
            height_data[hero_id] = float(height)

# Parse publisher section
pub_data = {}
for line in lines[-38:]:
    parts = line.split(',')
    if len(parts) == 3:
        hero_id = parts[0].strip()
        pub_id = parts[2].strip()
        if pub_id and pub_id != 'None':
            pub_data[hero_id] = int(pub_id)

# Merge by hero_id
merged = {}
for hid in set(height_data.keys()) & set(pub_data.keys()):
    merged[hid] = {'height': height_data[hid], 'pub_id': pub_data[hid]}

print(f'Merged count: {len(merged)}')

# Filter height 150-180
filtered = [d for d in merged.values() if 150 <= d['height'] <= 180]
print(f'Heroes with height 150-180: {len(filtered)}')
for h in filtered[:10]:
    print(h)

# Count Marvel (publisher_id=13)
marvel_count = sum(1 for d in filtered if d['pub_id'] == 13)
print(f'Marvel count in range: {marvel_count}')

if len(filtered) > 0:
    percentage = (marvel_count / len(filtered)) * 100
    print(f'Percentage: {percentage}')
else:
    print('No heroes in range')

